    22	function validateCardNumber(value: string): boolean {
    23	    let sum = 0;
    24	    let shouldDouble = false;
    25	
    26	    // Loop through the card number from right to left
    27	    for (let i = value.length - 1; i >= 0; i--) {
    28	        let intVal = parseInt(value[i], 10);
    29	
    30	        // Double every second digit from the right
    31	        if (shouldDouble) {
    32	            intVal *= 2;
    33	            if (intVal > 9) {
    34	                intVal -= 9;
    35	            }
    36	        }
    37	
    38	        sum += intVal;
    39	        shouldDouble = !shouldDouble;
    40	    }
    41	
    42	    return sum % 10 === 0;
    43	}
